#!/usr/bin/env bash
# Regenerate diffs/<case>.diff from baseline/ + cases/<case>/.
#
# The diff is what the reviewer actually sees, so it is generated by git rather
# than written by hand: hunk headers and line numbers have to be real or the
# engine's citation-grounding gate drops every finding.
#
# The fixture already carries real repo-shaped paths (server/src/modules/...),
# so the temp-dir prefix is stripped and nothing is substituted for it.
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

# ---------------------------------------------------------------------------
# Leak guard. A fixture that states the rule it is testing hands the answer to
# every arm, including the zero baseline — and the run still looks successful,
# because everything scores 11/11. This has happened: a repo-map annotation and
# a `$comment` header in a fixture file gave away four plants at once.
#
# The fixture is DIFF MATERIAL. It may contain violations; it may not contain
# sentences explaining them.
# ---------------------------------------------------------------------------
LEAK_RE='gitignor|never regenerate|must not be|do not (edit|commit|regenerate)|deliberately|on purpose|intentional|planted|violation of|breaks the rule|authoritative copy|mirror of|hermetic lane'
if leaks="$(grep -rniE "$LEAK_RE" "$here/baseline" "$here/cases" "$here/repo-map.md" 2>/dev/null)"; then
  printf 'LEAK: the fixture explains its own plants — the reviewer will read this and every arm scores alike.\n\n%s\n' "$leaks" >&2
  exit 1
fi

mkdir -p "$here/diffs"

for case_dir in "$here"/cases/*/; do
  name="$(basename "$case_dir")"
  rm -rf "$tmp/old" "$tmp/new"
  cp -R "$here/baseline" "$tmp/old"
  cp -R "$here/baseline" "$tmp/new"
  cp -R "$case_dir." "$tmp/new/"

  # --no-index exits 1 when there is a difference, which is the normal case.
  git -C "$tmp" diff --no-index --src-prefix=a/ --dst-prefix=b/ old new \
    | sed -E "s#(a/|b/)(old|new)/#\1#g" \
    > "$here/diffs/$name.diff" || true

  printf '%s: %s changed file(s)\n' "$name" \
    "$(grep -c '^diff --git' "$here/diffs/$name.diff" || true)"
done
